# Lore test-command interface (lore_list_tests / lore_run_test).
# Written for this repo's Jest suite rather than adapted from the Vitest
# equivalent for a Vitest suite: the report shapes happen to match, but the
# invocations do not.
- id: hal-engine-jest
  name: HAL Engine Jest suite
  cwd: .
  description: >-
    The ts-jest unit suite over src/ and scripts/ (jest.config.js roots), run
    on every pull request in .github/workflows/ci.yml as the "Test" step.
    Selectors are "<repo-relative-file>::<full test name>" as emitted by the
    list command. Jest has no dry-run, so the list command executes the suite
    once with --json and derives every name from the report; it deliberately
    tolerates a red suite, since listing must not depend on the tests passing.
    The run command selects one test with --runTestsByPath plus an anchored,
    regex-escaped -t, and treats a selector that matches nothing as a failure
    rather than a green run of an empty suite. Neither command builds first:
    no test here reads dist/.
  list: node scripts/lore-list-tests.mjs
  run: node scripts/lore-run-test.mjs "{selector}"
  coverage_format: lcov
import {createChatOrchestrator} from './chatOrchestrator.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import type {AIProvider, MessageChunk} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';

describe('onError rejection normalization', () => {
  it('preserves a non-Error rejection as its cause specs/hal-engine-config-hooks/spec.md#8', async () => {
    const reason = {code: 503};
    const provider: AIProvider = {
      // eslint-disable-next-line require-yield
      async *sendMessage(): AsyncGenerator<MessageChunk> {
        throw reason;
      },
      async generateStructured<T>(): Promise<T> {
        return {} as T;
      },
    };
    const session: ChatSession = {sessionId: 'session', userId: 'user', entries: []};
    const errors: Error[] = [];
    const orchestrator = createChatOrchestrator(provider, new PromptBuilder({identity: 'test'}), undefined, {
      hooks: {
        onError: async (_session, error) => {
          errors.push(error);
        },
      },
    });

    const thrown = await orchestrator.processMessage(session).then(
      () => undefined,
      (error: unknown) => error
    );
    expect({thrown, count: errors.length, isError: errors[0] instanceof Error, cause: errors[0]?.cause}).toEqual({
      thrown: reason,
      count: 1,
      isError: true,
      cause: reason,
    });
  });
});
import {createChatOrchestrator} from './chatOrchestrator.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import type {AIProvider, MessageChunk} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';

describe('onError rejection normalization', () => {
  it('preserves a rejection whose string conversion throws specs/hal-engine-config-hooks/spec.md#8', async () => {
    const reason = {
      toString: () => {
        throw new Error('conversion failed');
      },
    };
    const provider: AIProvider = {
      // eslint-disable-next-line require-yield
      async *sendMessage(): AsyncGenerator<MessageChunk> {
        throw reason;
      },
      async generateStructured<T>(): Promise<T> {
        return {} as T;
      },
    };
    const session: ChatSession = {sessionId: 'session', userId: 'user', entries: []};
    let seen: Error | undefined;
    const orchestrator = createChatOrchestrator(provider, new PromptBuilder({identity: 'test'}), undefined, {
      hooks: {
        onError: async (_session, error) => {
          seen = error;
        },
      },
    });
    const thrown = await orchestrator.processMessage(session).then(
      () => undefined,
      (error: unknown) => error
    );
    expect({thrown, isError: seen instanceof Error, cause: seen?.cause, message: seen?.message}).toEqual({
      thrown: reason,
      isError: true,
      cause: reason,
      message: expect.any(String),
    });
  });
});
